[{"type":"heading","data":{"textEn":"Tool Use and Function Calling","textKn":"Tool Use ಮತ್ತು Function Calling","level":"H1"}},{"type":"concept","data":{"headingEn":"Lesson Info","headingKn":"Lesson ಮಾಹಿತಿ","bodyEn":"• Type: Concept + Build · Language: Python (stdlib only) · Prerequisites: Modules 273-277 · Time: ~40 minutes","bodyKn":"• Type: Concept + Build · Language: Python (stdlib only) · Prerequisites: Modules 273-277 · Time: ~40 ನಿಮಿಷಗಳು","pillsEn":"Function Calling,JSON Schema,Validation,Tool Use","pillsKn":"Function Calling,JSON Schema,Validation,Tool Use"}},{"type":"heading","data":{"textEn":"Defining a Real Tool Schema","textKn":"ಒಂದೂ ನಿಜ Tool Schema ವ್ಯಾಖ್ಯಾನಿಸುವುದೂ","level":"H2"}},{"type":"concept","data":{"headingEn":"From "action" String to a Structured Contract","headingKn":""action" String ಇಂದ ಒಂದೂ ರಚನಾತ್ಮಕ Contract ಗೆ","bodyEn":"Modules 273-274's tools were called with plain Python tuples. Real function calling uses a JSON schema describing exactly which parameters exist, their types, and any allowed values -- so a model's raw output can be checked against a real contract before anything executes.","bodyKn":"Modules 273-274 ya tools ಅನ್ನೂ ಸರಳ ಪೈಥಾನ್ tuples ಜೊತೆ ಕರೆಯಲಾಯಿತೂ. ನಿಜ function calling ಒಂದೂ JSON schema ಬಳಸುತ್ತದೆ."}},{"type":"code","data":{"filename":"function_calling.py","headingEn":"code for concepts","headingKn":"concepts ಗಾಗಿ code","descEn":"A real get_weather tool with a JSON-schema definition, genuinely validated against one well-formed and one malformed raw call, executing only the valid one.","descKn":"ಒಂದೂ ನಿಜ get_weather tool ಒಂದೂ JSON-schema ವ್ಯಾಖ್ಯಾನದೊಂದಿಗೆ, ಒಂದೂ ಸರಿಯಾಗಿ ರೂಪುಗೊಂಡ, ಒಂದೂ ಅಸಮರ್ಪಕ raw call ವಿರುದ್ಧ ನಿಜವಾಗಿ validate ಮಾಡಲಾಗಿದೆ.","code":"import json

TOOL_SCHEMA = {
    'name': 'get_weather',
    'parameters': {
        'type': 'object',
        'properties': {
            'city': {'type': 'string'},
            'units': {'type': 'string', 'enum': ['celsius', 'fahrenheit']}
        },
        'required': ['city']
    }
}

def get_weather(city, units='celsius'):
    fake_db = {'tokyo': 18, 'paris': 12}
    temp = fake_db.get(city.lower())
    if temp is None:
        raise ValueError(f'no weather data for {city}')
    if units == 'fahrenheit':
        temp = temp * 9/5 + 32
    return {'city': city, 'temp': temp, 'units': units}

def validate_call(schema, args):
    props = schema['parameters']['properties']
    required = schema['parameters'].get('required', [])
    errors = []
    for r in required:
        if r not in args:
            errors.append(f'missing required parameter: {r}')
    for k, v in args.items():
        if k not in props:
            errors.append(f'unexpected parameter: {k}')
            continue
        expected_type = props[k]['type']
        if expected_type == 'string' and not isinstance(v, str):
            errors.append(f'{k}: expected string, got {type(v).__name__}')
        if 'enum' in props[k] and v not in props[k]['enum']:
            errors.append(f'{k}: {v!r} not in allowed values {props[k]["enum"]}')
    return errors

raw_call_1 = '{"city": "Tokyo", "units": "celsius"}'
raw_call_2 = '{"units": "kelvin"}'

for raw in [raw_call_1, raw_call_2]:
    args = json.loads(raw)
    errors = validate_call(TOOL_SCHEMA, args)
    print(f'call: {raw}')
    if errors:
        print('  REJECTED:', errors)
    else:
        result = get_weather(**args)
        print('  EXECUTED:', result)"}},{"type":"output","data":{"output":"call: {"city": "Tokyo", "units": "celsius"}
